	std::string escape_json_string(const std::string& value)
	{
		static const char hex[] = "0123456789abcdef";
		std::string escaped;
		escaped.reserve(value.size());
		for (unsigned char ch : value) {
			switch (ch) {
			case '"': escaped += "\\\""; break;
			case '\\': escaped += "\\\\"; break;
			default:
