	else {
		original_module = peconv::load_pe_module(szModName, original_size, false, false);
	}

	if (isRedirDisabled) {
		wow64_revert_fs_redirection(old_val);
	}
	if (!original_module) {
		return false;
	}
	this->is_dot_net = isDotNetManagedCode();
	return true;
