	std::string module_name = RemoteModuleData::getModuleName(processHandle, mod_base);
	if (module_name.length() == 0) {
#ifdef _DEBUG
		std::cerr << "Could not retrieve the module name. Base: " << std::hex << mod_base << std::endl;
