	//!  A report from the headers scan, generated by HeadersScanner
	class HeadersScanReport : public ModuleScanReport
	{
	public:
		HeadersScanReport(HMODULE _module, size_t _moduleSize)
			: ModuleScanReport(_module, _moduleSize),
