Inputs and classification function:

```
InjectionAssessment classifyPatchInjection(const PatchInjectionContext& ctx)
{
  if (ctx.isRelocated) benign: type NONE, verdict BENIGN, confidence 100, reason "relocation_entry", evidence ...
  if (ctx.paddingPatch || ctx.breakpoint) benign type NONE...
  if (ctx.importThunk) benign...
  if (ctx.classicHotpatch) HOTPATCH benign confidence 98 reason...
  if (!ctx.hasTarget) {
     if (ctx.sourceWasPadding || ctx.sectionExpanded) {
        CODE_CAVE injected conf 92 reason "executable_code_in_unused_section_space"
     }
     if (ctx.sourceAtFunctionEntry && ctx.patchIsCode) HOTPATCH? Hmm no target, maybe function patched direct (hotpatch replacing code). Could mark HOTPATCH benign if original code and remote bytes valid code, but hard. Do not.
     return UNKNOWN suspicious conf 30 reason "unrecognized_code_modification"
  }
  // has flow target
  if (ctx.targetSameModule) {
     if (ctx.targetWasPadding) {
        if (ctx.targetHasCopiedPrologue || ctx.targetHasJumpBack) HOTPATCH benign conf 90 reason "trampoline_copies_original_prologue"
        else CODE_CAVE injected conf 85 reason "jump_into_unused_code_space"
     }
     if (ctx.targetInNamedModule) {
        if (ctx.sourceAtFunctionEntry) HOTPATCH benign conf 85 reason "entry_jump_within_named_module"
        else INLINE_HOOK suspicious conf 70 reason "jump_within_named_module_from_non_entry"
     }
     return UNKNOWN...
  }
  if (ctx.targetInNamedModule) {
     if (ctx.targetInSuspiciousModule) SHELLCODE_JUMP injected conf 90 reason "jump_to_suspicious_module"
     return INLINE_HOOK suspicious conf 75 reason "jump_to_named_module"
  }
  // outside known/named modules
  return SHELLCODE_JUMP injected conf 95 reason "jump_target_outside_named_modules"
}
```

