233	bool pesieve::HeadersScanner::isFileHdrModified(const PBYTE hdr_buffer1, const PBYTE hdr_buffer2, const size_t hdrs_size, bool mask_arch_mismatch)
234	{
235		const IMAGE_FILE_HEADER *file_hdr1 = peconv::get_file_hdr(hdr_buffer1, hdrs_size);
236		const IMAGE_FILE_HEADER *file_hdr2 = peconv::get_file_hdr(hdr_buffer2, hdrs_size);
237	
238		if (!file_hdr1 && !file_hdr2) return false;
239		if (!file_hdr1 || !file_hdr2) return true;
240	
241		if (memcmp(file_hdr1, file_hdr2, sizeof(IMAGE_FILE_HEADER)) == 0) {
242			return false;
243		}
244		if (mask_arch_mismatch) {
245			if (file_hdr1->Machine == file_hdr2->Machine
246				&& file_hdr1->Characteristics == file_hdr2->Characteristics
247				&& file_hdr1->NumberOfSections == file_hdr2->NumberOfSections
248				&& file_hdr1->TimeDateStamp == file_hdr2->TimeDateStamp
249				&& file_hdr1->SizeOfOptionalHeader != file_hdr2->SizeOfOptionalHeader)
250			{
251				// only the SizeOfOptionalHeader has changed
252				return false;
253			}
254		}
255		return true;
256	}
