+		if (code[i] == OP_JMP && i + 5 <= max_scan) {
+			int32_t delta = 0;
+			memcpy(&delta, code + i + 1, sizeof(delta));
+			if (getJmpDestAddr<int32_t>(currVa, 5, delta) == destination) {
